import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode="fast", level="3".

    keys[i] is set to values[i]. Returns the resulting values: first the
    value of "mode", then the value of "level", then the values of all
    other keys in the order they first appear in `keys`. If a key repeats,
    the last value given for it wins, and it keeps the position of its
    first appearance.

    Raises ValueError if keys and values have different lengths.
    Pure: reads no files or environment and has no side effects.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "slow"]) == ["slow", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extra_keys_mixed_with_defaults() -> None:
    keys = ["x", "level", "y", "mode"]
    values = ["10", "5", "20", "turbo"]
    assert settings(keys, values) == ["turbo", "5", "10", "20"]


def test_duplicate_extra_key_last_wins_first_position() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_default_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values() -> None:
    assert settings(["mode", "k"], ["", ""]) == ["", "3", ""]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings(["a"], ["1", "2"])


def test_inputs_not_mutated() -> None:
    keys = ["mode", "q"]
    values = ["slow", "1"]
    settings(keys, values)
    assert keys == ["mode", "q"]
    assert values == ["slow", "1"]
